// Parse the Groq JSON output into a proper JSON object
const response = $input.first().json;
const raw = response.choices?.[0]?.message?.content || response.text || '';

let story;
try {
  const cleaned = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
  story = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Story Generator returned invalid JSON. Raw output: ' + raw.substring(0, 300));
}

if (!story.episodes || !Array.isArray(story.episodes)) {
  throw new Error('Story JSON missing episodes array');
}

return [{ json: story }];

// Flatten story into individual scene items for the loop
const story = $input.first().json;
const allScenes = [];

story.episodes.forEach(episode => {
  if (!Array.isArray(episode.scenes)) return;
  episode.scenes.forEach(scene => {
    allScenes.push({
      story_title: story.title,
      story_genre: story.genre,
      story_theme: story.theme,
      characters: story.characters || [],
      episode_number: episode.episode_number,
      episode_title: episode.title,
      scene_number: scene.scene_number,
      description: scene.description,
      dialogue_speaker: scene.dialogue?.speaker || '',
      dialogue_text: scene.dialogue?.text || '',
      asset_key: `ep${episode.episode_number}_sc${scene.scene_number}`
    });
  });
});

if (allScenes.length === 0) {
  throw new Error('No scenes found in story');
}

return allScenes.map(s => ({ json: s }));

// Build a rich cinematic prompt for image generation
const scene = $input.first().json;

const characters = scene.characters || [];
const speaker = characters.find(c => c.name === scene.dialogue_speaker);
const charDesc = speaker ? `, ${speaker.appearance}` : '';

const platformComposition = {
  'TikTok': 'vertical 9:16 composition, close-up framing',
  'Shorts': 'vertical 9:16 composition, dynamic angle',
  'Reels': 'vertical 9:16 composition, cinematic framing',
  'default': 'cinematic wide shot'
};
const composition = platformComposition[scene.target_platform] || platformComposition.default;

const genreStyle = {
  'Fantasy': 'fantasy art style, magical lighting, ethereal atmosphere',
  'Sci-Fi': 'sci-fi concept art, futuristic neon lighting, cyberpunk aesthetic',
  'Horror': 'dark gothic atmosphere, dramatic shadows, ominous lighting',
  'Romance': 'soft warm lighting, pastel color palette, dreamy atmosphere',
  'Adventure': 'epic cinematic lighting, vivid colors, dynamic composition',
  'Drama': 'realistic style, natural lighting, emotional depth'
};
const style = genreStyle[scene.story_genre] || 'cinematic art style, dramatic lighting';

const prompt = [
  scene.description,
  charDesc,
  style,
  composition,
  'ultra detailed, 4K, film grain, professional photography'
].filter(Boolean).join(', ');

return [{
  json: {
    ...scene,
    image_prompt: prompt
  }
}];

// Extract image URL from HuggingFace response
const response = $input.first().json;
const scene = $('Generate Image Prompt').first().json;

let imageUrl = null;

// Handle different response formats
if (Array.isArray(response) && response[0]) {
  imageUrl = response[0].url || response[0].base64;
} else if (response.image) {
  imageUrl = response.image;
} else if (response.url) {
  imageUrl = response.url;
}

// If base64, create data URL
if (imageUrl && !imageUrl.startsWith('http')) {
  imageUrl = `data:image/png;base64,${imageUrl}`;
}

if (!imageUrl) {
  // Fallback: use a placeholder or retry
  throw new Error('No image in HuggingFace response: ' + JSON.stringify(response).substring(0, 200));
}

return [{
  json: {
    ...scene,
    image_url: imageUrl,
    image_base64: imageUrl.startsWith('data:') ? imageUrl.split(',')[1] : null
  }
}];

// Prepare speech bubble data
const binaryData = $input.first().binary;
const scene = $('Extract Image URL').first().json;

const imageBase64 = binaryData?.data?.data
  ? Buffer.from(binaryData.data.data).toString('base64')
  : null;

return [{
  json: {
    ...scene,
    image_base64: imageBase64,
    bubble_text: scene.dialogue_text,
    speaker_name: scene.dialogue_speaker,
    has_dialogue: Boolean(scene.dialogue_text)
  }
}];

// Merge bubble render result
const bubbleResult = $input.first().json;
const scene = $('Prepare Speech Bubble Data').first().json;

return [{
  json: {
    ...scene,
    final_image_url: bubbleResult.output_url || scene.image_url,
    final_image_base64: bubbleResult.output_base64 || scene.image_base64,
    bubble_rendered: bubbleResult.success || false
  }
}];

// Merge voice result with scene data
const voiceResult = $input.first().json;
const scene = $('Bubble Render Result').first().json;

return [{
  json: {
    asset_key: scene.asset_key,
    episode_number: scene.episode_number,
    episode_title: scene.episode_title,
    scene_number: scene.scene_number,
    description: scene.description,
    dialogue_speaker: scene.dialogue_speaker,
    dialogue_text: scene.dialogue_text,
    image_url: scene.final_image_url,
    final_image_base64: scene.final_image_base64,
    voice_url: voiceResult.output_path || `storage://voices/${scene.asset_key}.mp3`,
    voice_base64: voiceResult.audio_base64 || null,
    bubble_rendered: scene.bubble_rendered,
    status: 'scene_complete'
  }
}];

// Collect all completed scenes and group by episode
const allScenes = $input.all().map(item => item.json);

if (allScenes.length === 0) {
  throw new Error('No completed scenes to merge');
}

const episodeMap = {};
allScenes.forEach(scene => {
  const epKey = scene.episode_number;
  if (!episodeMap[epKey]) {
    episodeMap[epKey] = {
      episode_number: epKey,
      episode_title: scene.episode_title,
      scenes: []
    };
  }
  episodeMap[epKey].scenes.push(scene);
});

Object.values(episodeMap).forEach(ep => {
  ep.scenes.sort((a, b) => a.scene_number - b.scene_number);
});

const episodes = Object.values(episodeMap).sort((a, b) => a.episode_number - b.episode_number);

return [{
  json: {
    story_title: allScenes[0]?.story_title || 'Untitled',
    total_scenes: allScenes.length,
    total_episodes: episodes.length,
    episodes: episodes,
    all_scenes: allScenes,
    status: 'ready_for_render'
  }
}];

// Build final response
const renderResult = $input.first().json;
const assetData = $('Merge All Assets').first().json;

const response = {
  success: true,
  story_title: assetData.story_title,
  total_scenes: assetData.total_scenes,
  total_episodes: assetData.total_episodes,
  video_url: renderResult.output_path || null,
  video_duration_seconds: renderResult.duration || null,
  thumbnail_url: renderResult.thumbnail || null,
  episodes: assetData.episodes.map(ep => ({
    episode_number: ep.episode_number,
    episode_title: ep.episode_title,
    scenes: ep.scenes.map(sc => ({
      scene_number: sc.scene_number,
      image_url: sc.image_url,
      voice_url: sc.voice_url,
      dialogue: { speaker: sc.dialogue_speaker, text: sc.dialogue_text }
    }))
  })),
  render_status: renderResult.status || 'unknown',
  created_at: new Date().toISOString()
};

return [{ json: response }];
